function auditPortfolioData({currency='TRY',months=DISPLAY_DATA,order=MONTH_ORDER,trades=RECORDED_TRADES,dividends=DIVIDEND_ROWS,positionRows=null}={}) {
 const findings=[],monthResults=[];let checks=0;
 const finite=v=>typeof v==='number'&&Number.isFinite(v);
 const add=(month,level,kind,code,message,detail='')=>findings.push({id:'audit-'+findings.length,month,level,kind,code,message,detail});
 const check=(ok,month,level,kind,code,message,detail='')=>{checks++;if(!ok)add(month,level,kind,code,message,detail)};
 let currentRate=1;
 const qtyText=v=>number(v,9),cash=v=>currency==='USD'?currentRate>0?'$'+number(v/currentRate,2):'Kur eksik':'₺'+number(v,2);
 const key=p=>JSON.stringify([p.platform||p.institution,p.code,p.group]);
 const validDate=s=>{if(typeof s!=='string'||!/^\d{2}\/\d{2}\/\d{2}$/.test(s))return null;const [d,m,y]=s.split('/').map(Number),date=new Date(Date.UTC(2000+y,m-1,d));return date.getUTCFullYear()===2000+y&&date.getUTCMonth()===m-1&&date.getUTCDate()===d?date:null};
 const summaryGroups={hisse:'Hisse Senetleri',fon:'Yatırım Fonları',altin:'Kıymetli Madenler',bitcoin:'Bitcoin',voo:"ETF'ler"};
 const allowed=new Set([...ALLOWED_INVESTMENT_INSTITUTIONS,'Fiziki Altın']);
 const missingMonths=order.filter(k=>!months[k]);
 if(missingMonths.length)return {findings:missingMonths.map((k,i)=>({id:'missing-'+i,month:k,level:'error',kind:'Ay kaydı',code:'',message:'Arşivde ay kaydı bulunamadı.',detail:''})),monthResults:[],checks:missingMonths.length};
 const positions=Object.fromEntries(order.map(k=>[k,positionRows?.[k]||monthPositions(months[k])]));
 order.forEach((k,mi)=>{
  const m=months[k],rows=positions[k],startChecks=checks,startFindings=findings.length;
  const sum=rows.reduce((s,p)=>s+(finite(p.value)?p.value:0),0),fx=monthRate(m);currentRate=fx;
  check(finite(fx)&&fx>0,k,'error','Kur','','Pozitif ve geçerli USD/TL kuru yok.');
  check(finite(m.total_try)&&Math.abs(sum-m.total_try)<=.05,k,'error','Toplam','','Pozisyon toplamı ile portföy toplamı uyuşmuyor.',`Pozisyonlar ${cash(sum)}; portföy ${cash(m.total_try)}; fark ${cash(sum-m.total_try)}.`);
  const summarySum=(m.summary||[]).reduce((s,c)=>s+(finite(c.value_try)?c.value_try:0),0);
  check(Math.abs(summarySum-m.total_try)<=.05,k,'error','Kategori toplamı','','Kategori toplamları portföy toplamına eşit değil.',`Kategori toplamı ${cash(summarySum)}; portföy ${cash(m.total_try)}.`);
  Object.entries(summaryGroups).forEach(([category,group])=>{const part=rows.filter(p=>p.group===group).reduce((s,p)=>s+(finite(p.value)?p.value:0),0),summaries=(m.summary||[]).filter(c=>c.key===category);check(summaries.length===1&&finite(summaries[0]?.value_try)&&Math.abs(summaries[0].value_try-part)<=.05,k,'error','Kategori toplamı',group,'Kategori özeti ile pozisyonlar uyuşmuyor.',`Pozisyonlar ${cash(part)}; özet ${cash(summaries[0]?.value_try)}.`)});
  const seen=new Set();
  rows.forEach(p=>{
   check(!seen.has(key(p)),k,'error','Tekrarlanan pozisyon',p.code,'Aynı kurum ve varlık için birden fazla pozisyon satırı var.',p.platform);seen.add(key(p));
   check(allowed.has(p.platform),k,'error','Kapsam',p.code,'İzin verilen yatırım hesapları dışında pozisyon var.',p.platform);
   check(!(p.platform==='İş Bankası'&&['BINHO','KOCMT','PATEK'].includes(p.code)),k,'error','Hariç pozisyon',p.code,'Hariç tutulması istenen küsuratlı hisse toplamda yer alıyor.');
   check(finite(p.qty)&&p.qty>0,k,'error','Adet',p.code,'Pozisyon adedi eksik veya geçersiz.',p.platform);
   check(finite(p.value)&&p.value>=0,k,'error','Değer',p.code,'Pozisyon değeri eksik veya geçersiz.',p.platform);
   check(p.cost==null||(finite(p.cost)&&p.cost>=0),k,'error','Maliyet',p.code,'Pozisyon maliyeti geçersiz.',p.platform);
   check(finite(p.price)&&p.price>0,k,'warning','Fiyat',p.code,'Pozisyon fiyatı eksik veya geçersiz.',p.platform);
   if(finite(p.qty)&&finite(p.price)&&finite(p.value)&&finite(fx)){
    const expected=p.qty*p.price*(p.native==='USD'?fx:1),tolerance=Math.max(.05,Math.abs(p.value)*.0001);
    check(Math.abs(expected-p.value)<=tolerance,k,p.monthlyPriceReference?'info':'warning','Fiyat / değer',p.code,p.monthlyPriceReference?'Karşılaştırma fiyatı, ekstre değerinden farklı bir referans kullanıyor.':'Adet × fiyat ile kayıtlı değer arasında fark var.',`${p.platform}; fiyatla hesaplanan ${cash(expected)}, kayıtlı ${cash(p.value)}. Yuvarlama veya kaynak fiyat tarihi incelenmeli.`);
   }
   if(p.monthlyPriceReference){const ref=p.monthlyPriceReference,end=String(m.report_date).split('.').reverse().join('-');check(ref.end.date<=end,k,'error','Fiyat tarihi',p.code,'Fiyat referansı ay sonrasına ait.',ref.end.date);if(ref.end.date<end)add(k,'info','Fiyat tarihi',p.code,'Fiyat referansı ayın son gününden önceye ait.',`${ref.end.date}; kaynak: ${ref.source}.`)}
  });
  const noCost=rows.filter(p=>!finite(p.cost)),refCost=rows.filter(p=>p.costReferenceDate),noMonthly=mi?rows.filter(p=>!finite(p.monthlyPct)):[];
  if(noCost.length)add(k,'info','Eksik maliyet','',`${noCost.length} pozisyonda doğrulanmış maliyet bulunmuyor.`,noCost.map(p=>p.code).join(', '));
  if(refCost.length)add(k,'info','Maliyet referansı','',`${refCost.length} fonda 21 Ekim maliyeti referans alınıyor.`,refCost.map(p=>p.code).join(', ')+'. Geçmiş ayın doğrulanmış maliyeti değildir.');
  if(noMonthly.length)add(k,'info','Aylık fiyat','',`${noMonthly.length} pozisyonda aylık fiyat karşılaştırması yok.`,noMonthly.map(p=>p.code+': '+(p.monthlyPriceNote||'Önceki fiyat eksik')).join('; '));
  if(m.btc_estimate)add(k,'info','Kullanıcı onaylı tahmin','Bitcoin','Haziran adedi ve maliyeti Temmuz ekstresinden geriye taşındı.',m.btc_estimate.method+' Haziran alış tutarı: '+cash(BTC_JUNE_BUY_EVIDENCE.reduce((n,r)=>n+r.amount,0))+'. Kesin adet veya işlem fiyatı olarak doğrulanmış değildir.');

  const monthTrades=trades.filter(t=>t.month===k),fingerprints=new Map();
  monthTrades.forEach(t=>{
   const date=validDate(t.date),reportYear=Number(String(m.report_date).slice(-4));
   check(date&&date.getUTCMonth()===mi&&date.getUTCFullYear()===reportYear&&t.mi===mi,k,'error','İşlem tarihi',t.code,'İşlem tarihi arşiv ayıyla uyuşmuyor.',t.date);
   const approvedEstimate=t.estimatedQty===true&&t.id.startsWith('btc-june-estimate-')&&t.month==='HAZİRAN'&&t.code==='Bitcoin'&&t.price===null&&t.fee===null;
   check(['A','S'].includes(t.side)&&['TRY','USD'].includes(t.currency??(t.institution==='Fiziki Altın'?'TRY':null))&&finite(t.qty)&&t.qty>0&&(approvedEstimate||(finite(t.price)&&t.price>0&&finite(t.fee)&&t.fee>=0))&&finite(t.amount)&&t.amount>=0,k,'error','İşlem alanı',t.code,'İşlem yönü, para birimi, adet, fiyat, tutar veya ücret geçersiz.',t.date);
   check(allowed.has(t.institution),k,'error','Kapsam',t.code,'İşlem izin verilen hesaplar dışında.',t.institution);
   const fingerprint=JSON.stringify([t.date,t.time||'',t.code,t.side,t.institution,t.qty,t.price,t.amount,t.fee]);
   if(fingerprints.has(fingerprint))add(k,'warning','Olası tekrar',t.code,'Aynı tarih/saat ve tutarda birden fazla işlem var.',`${t.date} ${t.time||''}; otomatik silinmedi.`);else fingerprints.set(fingerprint,t.id);checks++;
   if([t.qty,t.price,t.amount,t.fee].every(finite)){
    const calculated=t.qty*t.price,tolerance=Math.max(.05,t.qty*.005*(t.currency==='USD'?fx:1),Math.abs(t.amount)*.00001)+t.fee;
    check(Math.abs(calculated-t.amount)<=tolerance,k,'warning','İşlem tutarı',t.code,'Adet × işlem fiyatı ile tutar uyuşmuyor.',`${t.date}; hesaplanan ${cash(calculated)}, kayıtlı ${cash(t.amount)}. Ücret ve fiyat yuvarlaması toleransı uygulanır.`);
   }
  });
  if(mi){
   const prior=new Map(positions[order[mi-1]].map(p=>[key(p),p])),current=new Map(rows.map(p=>[key(p),p]));
   const movements=new Map();monthTrades.forEach(t=>{const id=key(t);movements.set(id,(movements.get(id)||0)+(t.side==='A'?t.qty:t.side==='S'?-t.qty:0))});
   new Set([...prior.keys(),...current.keys(),...movements.keys()]).forEach(id=>{
    const before=prior.get(id),after=current.get(id),movement=movements.get(id)||0,begin=before?.qty??0,end=after?.qty??0;
    if(!finite(begin)||!finite(end))return;
    const expected=begin+movement,code=(after||before)?.code||JSON.parse(id)[1],platform=(after||before)?.platform||JSON.parse(id)[0],tolerance=Math.max(['Bitcoin','ATOM'].includes(code)?1.1e-7:1e-8,Math.max(Math.abs(begin),Math.abs(end),Math.abs(movement))*1e-8);
    if(USER_AUDIT_RESOLUTIONS.ignoredQuantityReviews.includes(code))return;
    if(platform==='İş Bankası'&&USER_AUDIT_RESOLUTIONS.confirmedBankExits[k]?.includes(code)&&begin>0&&end===0&&movement===0){
     add(k,'info','Teyitli satış',code,'Pozisyonun tamamının satıldığı kullanıcı tarafından teyit edildi.',`${qtyText(begin)} adet. Satış geliri diğer hisse ve fonlara zaman içinde dağıtıldı. Kesin satış günü, fiyat ve tutar bulunmadığından işlem kaydı veya nakit girişi üretilmedi.`);return;
    }
    check(Math.abs(expected-end)<=tolerance,k,'warning','Adet uzlaştırma',code,'Ay sonu adedi kayıtlı alım-satımlarla tam açıklanamıyor.',`${platform}; önceki ay ${qtyText(begin)}, kayıtlı adet değişimi ${qtyText(movement)}, beklenen ${qtyText(expected)}, ay sonu ${qtyText(end)}. Eksik işlem, virman veya sermaye hareketi olabilir; otomatik düzeltme yapılmadı.`);
   });
  }
  const result=findings.slice(startFindings);monthResults.push({month:k,checks:checks-startChecks,errors:result.filter(f=>f.level==='error').length,warnings:result.filter(f=>f.level==='warning').length,notes:result.filter(f=>f.level==='info').length});
 });
 const tradeIds=new Set();trades.forEach(t=>{check(!tradeIds.has(t.id),t.month||'ARŞİV','error','İşlem kimliği',t.code,'Tekrarlanan işlem kimliği var.');tradeIds.add(t.id);check(order.includes(t.month),order.includes(t.month)?t.month:'ARŞİV','error','Arşiv dışı işlem',t.code,'İşlem için karşılık gelen ay kaydı yok.',t.date)});
 const dividendIds=new Set();dividends.forEach(d=>{const valid=typeof d.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d.date),date=valid?new Date(d.date+'T00:00:00Z'):null;check(!dividendIds.has(d.id),'TEMETTÜ','error','Temettü kimliği',d.code,'Tekrarlanan temettü kimliği var.');dividendIds.add(d.id);check(valid&&Number.isFinite(date?.getTime())&&date.toISOString().slice(0,10)===d.date&&finite(d.qty)&&d.qty>0&&finite(d.amount)&&d.amount>=0&&['TRY','USD'].includes(d.currency),'TEMETTÜ','error','Temettü alanı',d.code,'Temettü tarihi, adet, tutar veya para birimi eksik/geçersiz.',d.date)});
 // Separate sources may have legitimate same-day payments. Report identical payments for review, never auto-merge.
 const dividendSeen=new Set();dividends.forEach(d=>{const id=JSON.stringify([d.date,d.code,d.currency,d.amount,d.qty]);if(dividendSeen.has(id))add('TEMETTÜ','warning','Olası tekrar',d.code,'Aynı tarih, adet ve tutarda temettü kaydı var.',d.date);dividendSeen.add(id);checks++});
 monthResults.forEach(r=>{const list=findings.filter(f=>f.month===r.month);r.errors=list.filter(f=>f.level==='error').length;r.warnings=list.filter(f=>f.level==='warning').length;r.notes=list.filter(f=>f.level==='info').length});
 return {findings,monthResults,checks};
}

function DataQualityAudit({idx,currency}) {
 const [allMonths,setAllMonths]=useState(true),[showNotes,setShowNotes]=useState(false);
 const report=useMemo(()=>auditPortfolioData({currency}),[currency]),month=MONTH_ORDER[idx];
 const visible=report.findings.filter(f=>(allMonths||f.month===month||f.month==='TEMETTÜ'||f.month==='ARŞİV')&&(showNotes||f.level!=='info'));
 const errors=report.findings.filter(f=>f.level==='error').length,warnings=report.findings.filter(f=>f.level==='warning').length,notes=report.findings.filter(f=>f.level==='info').length;
 const label={error:'Uyuşmazlık',warning:'İncelenmeli',info:'Kaynak notu'},color={error:'#ff7184',warning:'#edbb43',info:'#9bbad9'};
 const monthName=k=>DISPLAY_DATA[k]?.display_name||({'TEMETTÜ':'Temettü arşivi','ARŞİV':'İşlem arşivi'}[k]||k);
 return <section className="pd-card" data-data-quality="true"><div className="pd-heading"><div><h2>Veri Kontrolü</h2><small>{MONTH_ORDER.length} ay · Pozisyon, işlem ve temettü arşivi</small></div><span style={{color:errors?color.error:warnings?color.warning:'#0ce8ad'}}>{errors?`${errors} uyuşmazlık`:warnings?`${warnings} inceleme kaydı`:'Kontrollerde uyuşmazlık bulunmadı'}</span></div>
 <div style={{display:'flex',flexWrap:'wrap',gap:'8px 22px',fontSize:12,margin:'14px 0'}}><span style={{color:color.error}}>Uyuşmazlık: <strong>{errors}</strong></span><span style={{color:color.warning}}>İncelenmeli: <strong>{warnings}</strong></span><span style={{color:color.info}}>Kaynak notu: <strong>{notes}</strong></span></div>
 <CollapsibleNote title="Kontrol yöntemi"><p className="pd-note">Bu kontrol kayıtların kendi içindeki tutarlılığını inceler; belgelerdeki her satırın yeniden doğrulandığı anlamına gelmez. Portföy ve kategori toplamları, fiyat/değer ilişkisi, tarih, hesap kapsamı, tekrarlar ve adet hareketleri kontrol edilir. Adet uzlaştırması: önceki ay adedi + alım − satış = ay sonu adedi. İlk ay için önceki ay karşılaştırması yoktur. QUICK ve CITAS adet incelemeleri kullanıcı talebiyle kapsam dışındadır. Teyitli fon satışları ve kullanıcı onaylı BTC tahmini kaynak notlarında açıklanır. Tahminle uzlaşan adetler, bağımsız ekstre doğrulaması anlamına gelmez. Kripto adetlerinde ekstre yuvarlaması için 0,00000011 adede kadar tolerans uygulanır. Temettü kayıtları ayrı denetlenir.</p></CollapsibleNote>
 <details style={{marginTop:14}}><summary style={{cursor:'pointer',fontSize:12}}>Ay bazında sonuçlar</summary><div className="pd-scroll" style={{marginTop:10}}><SortableTable><thead><tr><th>Ay</th><th>Uyuşmazlık</th><th>İncelenmeli</th><th>Kaynak notu</th></tr></thead><tbody>{report.monthResults.map(r=><tr key={r.month}><td>{monthName(r.month)}</td><td style={{color:r.errors?color.error:color.info}}>{r.errors}</td><td style={{color:r.warnings?color.warning:color.info}}>{r.warnings}</td><td>{r.notes}</td></tr>)}</tbody></SortableTable></div></details>
 <div className="pd-tools"><label><input type="checkbox" checked={allMonths} aria-label="Veri kontrolünde tüm ayları göster" onChange={e=>setAllMonths(e.target.checked)}/> Tüm ayları göster</label><label><input type="checkbox" checked={showNotes} aria-label="Veri kontrolünde kaynak notlarını göster" onChange={e=>setShowNotes(e.target.checked)}/> Kaynak notlarını göster</label></div><div aria-live="polite" className="pd-note" style={{margin:'0 0 8px'}}>{allMonths?'Tüm aylar':monthName(month)} · Temettü ve arşiv genelindeki bulgular her iki görünümde de gösterilir.</div>
 {visible.length?<div className="pd-scroll"><SortableTable data-audit-findings="true" style={{whiteSpace:'normal'}}><thead><tr><th>Ay</th><th>Durum</th><th>Kontrol</th><th>Varlık</th><th>Bulgu</th></tr></thead><tbody>{visible.map(f=><tr key={f.id}><td style={{whiteSpace:'nowrap'}}>{monthName(f.month)}</td><td style={{color:color[f.level],whiteSpace:'nowrap'}}>{label[f.level]}</td><td>{f.kind}</td><td>{f.code||'—'}</td><td style={{minWidth:240}}>{f.message}{f.detail&&<small style={{maxWidth:'none',marginTop:5,color:'#91adc4'}}>{f.detail}</small>}</td></tr>)}</tbody></SortableTable></div>:<p className="pd-note" role="status">Bu görünümde uyuşmazlık veya inceleme kaydı bulunmadı.{!showNotes?' Kaynak ve eksik maliyet açıklamaları için kaynak notlarını açabilirsin.':''}</p>}
 <p className="pd-note">Bulgular kayıtları değiştirmez. Olası tekrarlar silinmez; adet farkları için işlem üretilmez. Tarihi maliyet referansları, eksik karşılaştırma fiyatları ve varsayımlar kaynak notlarında tutulur. Sonuçlar dosyadaki güncel verilerden hesaplanır.</p></section>;
}

