function usePositionSorting() {
 const [sorting,setSorting]=useState({key:'value',direction:'desc'});
 const sortBy=key=>setSorting(current=>({key,direction:current.key===key?(current.direction==='desc'?'asc':'desc'):(key==='name'?'asc':'desc')}));
 return {sorting,sortBy};
}
function comparePositionRows(a,b,sorting,rate) {
 const get=p=>sorting.key==='name'?p.code:sorting.key==='share'?p.value:['cost','price'].includes(sorting.key)?(Number.isFinite(p[sorting.key])?p[sorting.key]*(p.native==='USD'?rate:1):null):p[sorting.key];
 const av=get(a),bv=get(b),missing=v=>v==null||(typeof v==='number'&&!Number.isFinite(v));
 if(missing(av)||missing(bv))return missing(av)===missing(bv)?a.code.localeCompare(b.code,'tr'):missing(av)?1:-1;
 const comparison=typeof av==='string'?av.localeCompare(bv,'tr'):av-bv;
 return (sorting.direction==='asc'?comparison:-comparison)||a.code.localeCompare(b.code,'tr')||String(a.platform||'').localeCompare(String(b.platform||''),'tr');
}
function SortHeading({field,label,sorting,onSort}) {
 const active=sorting.key===field,next=active?(sorting.direction==='desc'?'küçükten büyüğe':'büyükten küçüğe'):(field==='name'?'A’dan Z’ye':'büyükten küçüğe');
 return <th scope="col" aria-sort={active?(sorting.direction==='desc'?'descending':'ascending'):'none'}><button type="button" className={'pt-sort-heading'+(active?' pt-sort-active':'')} data-sort-field={field} aria-label={label+' · '+next+' sırala'} onClick={()=>onSort(field)}>{label}</button></th>;
}

function DividendIncome({currency}) {
 const [year,setYear]=useState('2026');
 const [sorting,setSorting]=useState({key:'date',direction:'desc'});
 const sortBy=key=>setSorting(s=>({key,direction:s.key===key?(s.direction==='desc'?'asc':'desc'):(key==='code'?'asc':'desc')}));
 const rows=DIVIDEND_ROWS.filter(r=>year==='Tümü'||r.date.startsWith(year));
 const equivalent=r=>r.amount*(r.currency==='USD'?LATEST_FX:1)/(currency==='USD'?LATEST_FX:1);
 const cash=v=>(currency==='USD'?'$':'₺')+number(v,2);
 const sum=list=>list.reduce((n,r)=>n+equivalent(r),0);
 const totals=c=>sum(rows.filter(r=>r.currency===c));
 const sorted=[...rows].sort((a,b)=>{const av=sorting.key==='amount'?equivalent(a):a[sorting.key],bv=sorting.key==='amount'?equivalent(b):b[sorting.key];if(av==null)return bv==null?0:1;if(bv==null)return -1;const v=typeof av==='number'?av-bv:String(av).localeCompare(String(bv),'tr');return (sorting.direction==='desc'?-v:v)||a.id.localeCompare(b.id)});
 const periods=year==='Tümü'?['2024','2025','2026'].map(y=>({label:y,value:sum(rows.filter(r=>r.date.startsWith(y)))})):Array.from({length:year==='2026'?10:12},(_,i)=>({label:['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'][i],value:sum(rows.filter(r=>Number(r.date.slice(5,7))===i+1))}));
 const max=Math.max(1,...periods.map(p=>p.value));
 const companies=[...new Set(rows.map(r=>r.code))].map(code=>({code,value:sum(rows.filter(r=>r.code===code))})).sort((a,b)=>b.value-a.value);
 return <>
 <section className="pd-card"><div className="pd-heading"><div><h2>Temettü Gelirleri</h2><small>2024–2026 · Kaydedilmiş ödemeler</small></div><label>Yıl &nbsp;<select aria-label="Temettü yılı" value={year} onChange={e=>setYear(e.target.value)}>{['2026','2025','2024','Tümü'].map(y=><option key={y}>{y}</option>)}</select></label></div>
 <div className="pd-stats"><div className="pd-metric"><small>TL ödemeleri</small><h2>{cash(totals('TRY'))}</h2></div><div className="pd-metric"><small>USD ödemeleri</small><h2>{cash(totals('USD'))}</h2></div><div className="pd-metric"><small>Ödeme sayısı</small><h2>{rows.length}</h2></div></div>
 <p className="pd-note">2026 kayıtları 2 Ekim’e kadardır; yıllık tahmin içermez. Gelirler portföy toplamına yeniden eklenmez. Para birimi dönüşümleri 21 Ekim 2026 referans kuru olan 49,587 TL ile gösterilir; tahsilat günü kuru kullanılmaz.</p></section>
 <div className="pd-two"><section className="pd-card"><h2>{year==='Tümü'?'Yıllık':'Aylık'} Gelir</h2><div role="img" aria-label="Dönemlere göre temettü gelirleri" style={{display:'grid',gap:10}}>{periods.map(p=><div key={p.label} style={{display:'grid',gridTemplateColumns:'34px minmax(30px,1fr) 100px',gap:10,alignItems:'center'}}><small>{p.label}</small><div style={{height:10,background:'#0a2b43',borderRadius:5}}><div style={{height:'100%',width:(p.value/max*100)+'%',background:'#12d8b1',borderRadius:5}}/></div><span style={{textAlign:'right',fontVariantNumeric:'tabular-nums'}}>{cash(p.value)}</span></div>)}</div></section>
 <section className="pd-card"><h2>En Çok Temettü Ödeyenler</h2>{companies.slice(0,5).map(c=><div key={c.code} style={{marginBottom:15}}><div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:12,marginBottom:7}}><span><AssetIcon code={c.code} group={c.code==='VOO'?'VOO (ETF)':'Hisse Senetleri'} size={24}/> {c.code}</span><strong>{cash(c.value)}</strong></div><div style={{height:5,background:'#0a2b43',borderRadius:5}}><div style={{height:'100%',width:(c.value/companies[0].value*100)+'%',background:'#12d8b1',borderRadius:5}}/></div></div>)}</section></div>
 <section className="pd-card"><h2>Ödeme Arşivi</h2><div className="pd-scroll"><SortableTable data-dividend-archive="true"><thead><tr>{[['date','Tarih'],['code','Varlık'],['qty','Ödemeye Esas Adet'],['amount','Tutar']].map(([field,label])=><SortHeading key={field} field={field} label={label} sorting={sorting} onSort={sortBy}/>)}<th>Kaynak</th></tr></thead><tbody>{sorted.map(r=><tr key={r.id}><td>{r.date.split('-').reverse().join('.')}</td><td><AssetIdentity code={r.code} name={FULL_NAMES[r.code]||r.name} group={r.code==='VOO'?'VOO (ETF)':'Hisse Senetleri'}/></td><td>{r.qty==null?'—':number(r.qty,r.code==='VOO'?9:4)}</td><td style={{whiteSpace:'nowrap'}}>{cash(equivalent(r))}{r.currency==='USD'&&<small style={{display:'block'}}>USD ödemesi</small>}</td><td>{r.sources.join(' + ')}</td></tr>)}</tbody></SortableTable></div><CollapsibleNote title="Temettü açıklamaları"><p className="pd-note">Adet, temettüye esas miktardır. Excel’de bulunmayan ENKAI ve LOGO adetleri, ekstredeki pozisyon ve işlem geçmişinden tamamlanmıştır. VOO adetleri dönem ekstrelerindeki pozisyon ve yeniden yatırım işlemlerinden çıkarılmıştır; temettüyle alınan ek paylar aynı ödemeye esas adede eklenmez. Aynı gün farklı adetlerle gelen ayrı ödemeler korunur. 12 Excel / ekstre eşleşmesi birer kez sayılmıştır.</p></CollapsibleNote></section>
 <section className="pd-card"><h2>Kayıt Kontrolü</h2><CollapsibleNote title="Kaynak notları"><p className="pd-note">2025 dosyasında metin biçimindeki dört ödeme toplam formülüne girmiyordu. Toplam 528,78 TL düzeltilerek 5.015,74 TL olarak alındı. Ekstrelerdeki ENKAI ve LOGO ödemeleri ile VOO’nun USD temettüleri de arşive eklendi. Kaynakta yazan ödeme tutarları kullanıldı; ayrıca vergi hesabı yapılmadı.</p></CollapsibleNote></section>
 </>;
}

function StockAllocation({positions,currency,rate,onSelect}) {
 const byCode=new Map();positions.forEach(p=>{const previous=byCode.get(p.code);byCode.set(p.code,{...p,value:(previous?.value||0)+p.value})});
 const palette=['#12d8b1','#5b9cf0','#e9b84e','#b58ade','#f08e67','#6dc9d3','#e783a9','#a6c967','#808cf0','#d4a36c','#56b89a','#a0b4d2','#d88567','#b3a5de','#c4ba67','#62b0e3','#cf8dc3','#78beb4','#ce9b9b','#98b877'];
 const allCodes=[...new Set(Object.values(DISPLAY_DATA).flatMap(m=>(m.stocks||[]).map(p=>p.code)))].sort();
 const rows=[...byCode.values()].filter(p=>p.value>0).sort((a,b)=>b.value-a.value).map(p=>({...p,color:palette[Math.max(0,allCodes.indexOf(p.code))%palette.length]}));
 const total=rows.reduce((s,p)=>s+p.value,0),cash=v=>(currency==='USD'?'$':'₺')+number(v/(currency==='USD'?rate:1),0);
 let angle=0;const gradient=rows.map(p=>{const from=angle;angle+=p.value/total*100;return `${p.color} ${from}% ${angle}%`}).join(',');
 return <section className="pd-card pd-stock-allocation" data-stock-allocation="true"><h2>Hisselerimin Dağılımı</h2>{total>0?<><div className="pd-stock-pie-layout"><div role="img" aria-label="Hisselerin seçilen aydaki değerlerine göre dağılımı" className="pd-stock-pie" style={{background:`conic-gradient(${gradient})`}}><div><small>Hisse Toplamı</small><strong>{cash(total)}</strong></div></div><div className="pd-stock-legend">{rows.map(p=><button key={p.code} type="button" data-stock-slice={p.code} data-stock-value={p.value} data-stock-share={p.value/total} onClick={()=>onSelect(p.code)} aria-label={p.code+' · hisselerin %'+number(p.value/total*100,2)+' kadarı · '+cash(p.value)}><span style={{display:'flex',alignItems:'center',gap:7,minWidth:0}}><i aria-hidden="true" style={{width:8,height:8,borderRadius:'50%',flexShrink:0,background:p.color}}/><AssetIcon code={p.code} group="Hisse Senetleri" size={19}/><span>{p.code}</span></span><strong>%{number(p.value/total*100,1)}</strong></button>)}</div></div><p className="pd-note">Seçilen ayın hisse değerlerine göre · Büyükten küçüğe sıralı. Bir hisseye tıklayarak ayrıntılarını açabilirsin.</p></>:<p className="pd-empty">Bu ay için kayıtlı hisse pozisyonu yok.</p>}</section>;
}

// Binary area partition: every positive holding keeps exactly its value share.
function weightedMapRects(values,width,height) {
 const total=values.reduce((sum,v)=>sum+(Number.isFinite(v)&&v>0?v:0),0),rects=values.map(()=>({x:0,y:0,width:0,height:0}));
 if(!total||width<=0||height<=0)return rects;
 const place=(items,x,y,w,h)=>{
  if(items.length===1){rects[items[0].i]={x,y,width:w,height:h};return}
  const sum=items.reduce((s,r)=>s+r.value,0);let part=0,cut=1,best=Infinity;
  for(let i=1;i<items.length;i++){part+=items[i-1].value;const diff=Math.abs(sum/2-part);if(diff<best){best=diff;cut=i}}
  const first=items.slice(0,cut),second=items.slice(cut),share=first.reduce((s,r)=>s+r.value,0)/sum;
  if(w>=h){place(first,x,y,w*share,h);place(second,x+w*share,y,w*(1-share),h)}
  else{place(first,x,y,w,h*share);place(second,x,y+h*share,w,h*(1-share))}
 };
 place(values.map((value,i)=>({value,i})).filter(r=>Number.isFinite(r.value)&&r.value>0),0,0,width,height);
 return rects;
}
function WeightedPositionMap({children,className,...props}) {
 const tiles=React.Children.toArray(children),values=tiles.map(t=>t.props['data-portfolio-value']??t.props['data-fund-value']??t.props['data-stock-value']??0),total=values.reduce((sum,v)=>sum+Math.max(0,v),0);
 return <div {...props} className={className+' pd-weighted-map pd-readable-weighted-map'} data-weighted-map="true">{tiles.map((tile,i)=>React.cloneElement(tile,{
  'data-map-share':total?values[i]/total:0,
  title:tile.props['aria-label'],
  style:{...tile.props.style},
  children:[...React.Children.toArray(tile.props.children),<span key="actual-weight" className="pd-map-actual-share" aria-label="Gösterilen varlıklar içindeki pay">{number(total?values[i]/total*100:0,2)}%</span>]
 }))}</div>;
}

