function portfolioMonthSummary(idx,currency='TRY') {
 const m=DISPLAY_DATA[MONTH_ORDER[idx]],rate=currency==='USD'?monthRate(m):1,performance=monthlyInvestmentReturn(idx,currency),trades=RECORDED_TRADES.filter(t=>t.mi===idx);
 const buy=trades.filter(t=>t.side==='A').reduce((s,t)=>s+t.amount/rate,0),sell=trades.filter(t=>t.side==='S').reduce((s,t)=>s+t.amount/rate,0);
 const cash=v=>(currency==='USD'?'$':'₺')+number(v,2),groups=DETAIL_GROUPS.map(group=>({group,buy:trades.filter(t=>t.group===group&&t.side==='A').reduce((s,t)=>s+t.amount/rate,0)})).sort((a,b)=>b.buy-a.buy);
 const known=performance.groups.filter(g=>Number.isFinite(g.gain)),best=[...known].filter(g=>g.gain>0).sort((a,b)=>b.gain-a.gain)[0],worst=[...known].filter(g=>g.gain<0).sort((a,b)=>a.gain-b.gain)[0];
 const missing=performance.groups.filter(g=>g.gain==null).map(g=>g.group),lines=[`Bu ay ${cash(buy)} alım, ${cash(sell)} satış kaydı var.${groups[0]?.buy>0?' Alımların en büyük kısmı '+groups[0].group+' grubunda.':''}`];
 lines.push(performance.gain==null?(idx?'Aylık toplam getiri hesaplanamıyor. Eksik veya kontrol bekleyen kayıtlar: '+missing.join(', ')+'.':'İlk arşiv ayı olduğu için aylık getiri hesaplanamıyor; önceki ayın portföy kaydı yok.'):`Alım-satım etkisi ayrılıp temettü ve fon dağıtımları dahil edildiğinde yatırımlarının aylık sonucu ${performance.gain>0?'+':''}${cash(performance.gain)}${performance.returnPct==null?'':(' ('+(performance.returnPct>0?'+':'')+number(performance.returnPct*100,2)+'%)')}.`);
 if(best||worst)lines.push((performance.gain==null?'Hesaplanabilen gruplarda: ':'')+[best&&`En yüksek kazanç ${best.group}: +${cash(best.gain)}`,worst&&`En büyük kayıp ${worst.group}: ${cash(worst.gain)}`].filter(Boolean).join(' · ')+'.');
 lines.push(`Ay sonunda yatırımlarının toplam değeri ${cash(m.total_try/rate)}. ₺10.000.000 hedefine ulaşma oranı %${number(m.total_try/TARGET_TRY*100,2)}.`);
 const notes=[...new Set([...(performance.notes||[]),...(performance.rateIssues||[]),...(performance.methodNotes||[])])];
 return {month:m.display_name+' '+m.report_date.slice(-4),currency,buy,sell,total:m.total_try/rate,performance,lines,notes};
}
function MonthlyNarrative({idx,currency}) {
 const summary=portfolioMonthSummary(idx,currency);
 return <details className="pt-card pt-month-summary" data-month-summary="true"><summary><span><UiIcon name="file-text" size={18}/> {summary.month} · Ayın Özeti</span><span className="pt-small">Aç / kapat</span></summary><div className="pt-month-summary-body">{summary.lines.map((line,i)=><p key={i}>{line}</p>)}<details className="pt-note"><summary>Yöntem ve kayıt notları</summary><p>Özet mevcut kayıtlardan otomatik hazırlanır. Alım ve satışlar kayıtlı işlem tutarlarıdır; getiri hesabında ücret sonrası nakit tutarları kullanılır. Getiri oranı Modified Dietz yöntemidir. Nakit bakiyesi ve hesap/saklama giderleri kapsam dışıdır. USD dönüşümlerinde her ayın kayıtlı kuru kullanılır.</p>{summary.notes.map((note,i)=><p key={i}>{note}</p>)}{summary.performance.issues.map((issue,i)=><p key={'issue-'+i}>{issue}</p>)}</details></div></details>;
}
