 sheet('Temettüler',['Tarih','Kod','Varlık adı','Adet','Özgün tutar','Özgün para birimi','Tutar ('+ccy+')','Dönüşüm notu'],dividends.map(d=>{const mi=MONTH_ORDER.findIndex(k=>{const m=DISPLAY_DATA[k];return d.date.startsWith(m.report_date.slice(-4)+'-'+String(MONTH_ORDER.indexOf(k)+1).padStart(2,'0'))}),fx=mi<0?null:monthRate(DISPLAY_DATA[MONTH_ORDER[mi]]),same=d.currency===currency,amount=same?d.amount:fx?d.amount*(d.currency==='USD'?fx:1)/(currency==='USD'?fx:1):null;return [d.date,d.code,d.name,d.qty,d.amount,d.currency,amount,same?'Dönüşüm gerekmiyor':fx?'Temettü ayının kayıtlı kuru':'Bu dönem için kayıtlı kur yok; özgün tutar korunmuştur']}),{3:'quantity',4:'money',6:'money'});
 const closureRows=closedPositionArchive(allMonths?MONTH_ORDER.length-1:idx).filter(r=>allMonths||r.mi===idx),closedAmount=(v,r)=>v==null?null:v*(r.bookCurrency==='USD'?monthRate(DISPLAY_DATA[MONTH_ORDER[r.mi]]):1)/(currency==='USD'?monthRate(DISPLAY_DATA[MONTH_ORDER[r.mi]]):1);
 sheet('Kapanan Pozisyonlar',['Varlık','Varlık adı','Varlık türü','Kapanış ayı','Doğrulanan kapanış tarihi','Satılan adet','Son kayıt adedi','Satılan maliyet ('+ccy+')','Net satış ('+ccy+')','Satış K/Z ('+ccy+')','Arşiv dönemi temettü ('+ccy+')','Temettü dahil K/Z ('+ccy+')','Durum','Notlar','MKK satış çıkış tarihi','MKK çıkış adedi','MKK satış blokaj tarihi'],closureRows.map(r=>[r.code,r.name,r.group,DISPLAY_DATA[MONTH_ORDER[r.mi]].display_name+' 2026',r.dateExact?r.closedDate:null,r.qtySold||null,r.missingExit?r.qty:null,closedAmount(r.cost,r),closedAmount(r.sale,r),closedAmount(r.pnl,r),closedAmount(r.dividend,r),closedAmount(r.totalPnl,r),r.status,r.notes.join('\n'),r.custodyExitDate||null,r.custodyQty??null,r.custodyBlockDate||null]),{5:'quantity',6:'quantity',7:'money',8:'money',9:'money',10:'money',11:'money',15:'quantity'});
